begin;
create temp table plan_fixture as select user_id u,partner_user_id p,gen_random_uuid() a,gen_random_uuid() b from partner_links where status='active' limit 1;
grant select on plan_fixture to authenticated;
insert into accounts(id,user_id,name,type,currency,current_balance) select a,u,'Cash planning fixture','checking','USD',1000 from plan_fixture union all select b,p,'Partner cash fixture','checking','USD',1000 from plan_fixture;
set local role authenticated;
do $$declare f record;g uuid;c uuid;stamp timestamptz;blocked boolean;n integer;begin
 select * into strict f from plan_fixture;perform set_config('request.jwt.claim.role','authenticated',true);perform set_config('request.jwt.claim.sub',f.u::text,true);
 g:=finance_save_goal(null,f.a,'Goal fixture',100,500,current_date+30);select updated_at into stamp from finance_documents where id=g;
 perform finance_save_goal(g,f.a,'Goal revised',150,600,current_date+40,stamp);blocked:=false;
 begin perform finance_save_goal(g,f.a,'Stale goal',150,600,current_date+40,stamp);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Stale goal overwritten';end if;
 blocked:=false;begin perform finance_save_goal(null,f.a,'Overallocated goal',900,1000,current_date+30);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Goal cash counted twice';end if;
 insert into finance_cash_plans(account_id,name,amount,first_date,frequency) values(f.a,'Fixture bill',-20,current_date+1,'monthly') returning id into c;
 insert into finance_cash_settings(owner_id,currency,buffer,variable_monthly,spending_account) values(f.u,'USD',100,300,f.a) on conflict(owner_id,currency) do update set buffer=excluded.buffer,variable_monthly=excluded.variable_monthly,spending_account=excluded.spending_account;
 if (select spending_account from finance_cash_settings where owner_id=f.u and currency='USD')<>f.a then raise exception 'Spending assumption account was not saved';end if;
 blocked:=false;begin update finance_cash_settings set spending_account=f.b where owner_id=f.u and currency='USD';exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Partner account accepted for assumptions';end if;
 update finance_cash_plans set status='paused' where id=c and revision=1;
 if (select revision from finance_cash_plans where id=c)<>2 then raise exception 'Revision missing';end if;
 if (select count(*) from finance_plan_history where record_id=c)<>2 then raise exception 'Plan audit missing';end if;
 blocked:=false;begin insert into finance_cash_plans(account_id,name,amount,first_date,frequency) values(f.b,'Not my account',-20,current_date+1,'once');exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Partner account accepted';end if;
 blocked:=false;begin delete from finance_documents where id=g;exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Goal history deleted';end if;
 select updated_at into stamp from finance_documents where id=g;perform finance_save_goal(g,null,'',0,0,null,stamp,true);
 if (select payload->>'reserved' from finance_documents where id=g)<>'0' or (select payload->>'status' from finance_documents where id=g)<>'archived' then raise exception 'Archive did not release cash';end if;
 perform set_config('request.jwt.claim.sub',f.p::text,true);
 if exists(select 1 from finance_cash_plans where id=c) or exists(select 1 from finance_plan_history where record_id=c) then raise exception 'Partner read private planning';end if;
 if exists(select 1 from finance_cash_settings where owner_id=f.u) then raise exception 'Partner read runway assumptions';end if;
 update finance_cash_plans set amount=-999 where id=c;get diagnostics n=row_count;if n<>0 then raise exception 'Partner updated cash plan';end if;
 blocked:=false;begin perform finance_save_goal(g,f.b,'Not mine',0,500,null,stamp);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Partner edited goal';end if;
end;$$;
reset role;
create temp table planning_reconnect as select u,a,gen_random_uuid() source_id from plan_fixture;
grant select on planning_reconnect to authenticated;
insert into accounts(id,user_id,name,type,currency,current_balance) select source_id,u,'Reconnected cash fixture','checking','USD',2000 from planning_reconnect;
update accounts set is_deleted=true where id in(select a from planning_reconnect);
insert into finance_account_continuity(owner_id,original_id,source_id,starts_on) select u,a,source_id,current_date from planning_reconnect;
set local role authenticated;
do $$declare f record;g uuid;begin
 select * into strict f from planning_reconnect;perform set_config('request.jwt.claim.sub',f.u::text,true);
 g:=finance_save_goal(null,f.a,'Reconnected goal',1800,2000,null);
 if (select payload->>'accountId' from finance_documents where id=g)<>f.a::text then raise exception 'Logical account identity changed';end if;
 insert into finance_cash_plans(account_id,name,amount,first_date,frequency) values(f.a,'Reconnected plan',-10,current_date+1,'once');
end;$$;
reset role;set local role anon;
do $$declare blocked boolean:=false;begin begin perform count(*) from finance_cash_plans;exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Anonymous planning access';end if;end;$$;
reset role;rollback;
select 'PASS: own account enforcement, private plans/history, version conflicts, reservation conservation and archive retention. Fixtures rolled back.' as result;
